 10	static void load_input(RawDataT *in, hls::stream<RawDataT> &inStream,
 11	                       uint64_t size) {
 12	  const uint64_t size_raw = size / kPackets;
 13	mem_rd:
 14	  for (uint64_t i = 0; i < size_raw; ++i) {
 15	#pragma HLS PIPELINE
 16	#pragma HLS LOOP_TRIPCOUNT min = kTotalMaxSize max = kTotalMaxSize avg =       \
 17	    kTotalMaxSize
 18	    inStream << in[i];
 19	  }
 20	}
 21	
 22	static void compute(hls::stream<RawDataT> &in1_stream,
 23	                    hls::stream<RawDataT> &in2_stream,
 24	                    hls::stream<RawDataT> &out_stream, uint64_t size, int op) {
 25	// The kernel is operating with vector of NUM_WORDS integers. The + operator
 26	// performs an element-wise add, resulting in NUM_WORDS parallel additions.
 27	execute:
 28	  for (uint64_t i = 0; i < size; i += kPackets) {
 29	#pragma HLS LOOP_TRIPCOUNT min = kTotalMaxSize max = kTotalMaxSize avg =       \
 30	    kTotalMaxSize
 31	#pragma HLS PIPELINE
 32	    RawDataT raw_in1 = in1_stream.read();
 33	    RawDataT raw_in2 = in2_stream.read();
 34	    RawDataT raw_out = 0;
 35	    for (int p = 0; p < kPackets; ++p) {
 36	#pragma HLS UNROLL
 37	      // Offsets
 38	      const int offlow = p * kDataWidth;
 39	      const int offhigh = offlow + kDataWidth - 1;
 40	
 41	      // Data
 42	      AccT in1, in2, out;
 43	#ifdef USE_UNION
 44	      in1.i = raw_in1(offhigh, offlow);
 45	      in2.i = raw_in2(offhigh, offlow);
 46	#else
 47	      in1.V = raw_in1(offhigh, offlow);
 48	      in2.V = raw_in2(offhigh, offlow);
 49	#endif
 50	      // Operation
 51	      switch (op) {
 52	      case OP_ADD:
 53	#ifdef USE_UNION
 54	        out.f = in1.f + in2.f;
 55	#else
 56	        out = in1 + in2;
 57	#endif
 58	        break;
 59	      case OP_MULT:
 60	#ifdef USE_UNION
 61	        out.f = in1.f * in2.f;
 62	#else
 63	        out = in1 * in2;
 64	#endif
 65	        break;
 66	      default:
 67	        out = in1;
 68	        break;
 69	      }
 70	
 71	      // Write back
 72	#ifdef USE_UNION
 73	      raw_out(offhigh, offlow) = out.i;
 74	#else
 75	      raw_out(offhigh, offlow) = out.V;
 76	#endif
 77	    }
 78	    out_stream << raw_out;
 79	  }
 80	}
 81	
 82	static void store_result(RawDataT *out, hls::stream<RawDataT> &out_stream,
 83	                         uint64_t size) {
 84	  const uint64_t size_raw = size / kPackets;
 85	mem_wr:
 86	  for (uint64_t i = 0; i < size_raw; ++i) {
 87	#pragma HLS PIPELINE
 88	#pragma HLS LOOP_TRIPCOUNT min = kTotalMaxSize max = kTotalMaxSize avg =       \
 89	    kTotalMaxSize
 90	    out[i] = out_stream.read();
 91	  }
 92	}
