 94	extern "C" {
 95	
 96	/*
 97	    Vector Addition Kernel
 98	
 99	    Arguments:
100	        in1  (input)  --> Input vector 1
101	        in2  (input)  --> Input vector 2
102	        out  (output) --> Output vector
103	        size (input)  --> Number of elements in vector
104	        op (input)    --> Operation: 0: add, 1: add+relu 2: mult
105	*/
106	
107	void elementwise(RawDataT *in1, RawDataT *in2, RawDataT *out, uint64_t size,
108	                 int op) {
109	#pragma HLS INTERFACE m_axi port = in1 bundle = gmem0
110	#pragma HLS INTERFACE m_axi port = in2 bundle = gmem1
111	#pragma HLS INTERFACE m_axi port = out bundle = gmem2
112	
113	  static StreamT in1_stream("in1_stream");
114	  static StreamT in2_stream("in2_stream");
115	  static StreamT out_stream("out_stream");
116	#pragma HLS stream variable = in1_stream depth = 32
117	#pragma HLS stream variable = in2_stream depth = 32
118	#pragma HLS stream variable = out_stream depth = 32
119	
120	#pragma HLS dataflow

